# pitch-mod helper: semitones -> % of coarse range (128 st span)
def st(semis):
    return round(semis / 1.28, 1)


def R(id_, name, category, genre, difficulty, lesson, summary, patch, fx, mistakes, source="practice"):
    return {"id": id_, "name": name, "category": category, "genre": genre, "difficulty": difficulty,
            "lessonId": lesson, "summary": summary, "patch": patch, "fxChain": fx, "commonMistakes": mistakes,
            "basis": source}

